from pathlib import Path
import base64

OUT = Path(__file__).resolve().parent
ROOT = next(p for p in OUT.parents if (p / "project.yml").exists())
avatar_path = OUT / 'avatar-reference.png'
if not avatar_path.exists():
    avatar_path = ROOT/'Shared/Resources/Companion.xcassets/DafeiyuStandingAvatar.imageset/DafeiyuStandingAvatar@3x.png'
avatar = base64.b64encode(avatar_path.read_bytes()).decode()

def ico(name):
    paths = {
        'search':'M17 17 23 23 M20 11a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
        'chat':'M4 4h17v13H10l-6 5z M8 9h9 M8 13h6',
        'book':'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M14 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',
        'check':'m6 13 4 4 10-11 M22 13v8H3V3h12',
        'star':'m13 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',
        'clock':'M13 6v7l4 2 M23 13a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    }
    return '<svg viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="'+paths[name]+'"/></svg>'

def chip(text, quiet=False):
    return '<span class="chip'+(' quiet' if quiet else '')+'">'+text+'</span>'

def search(text):
    return '<div class="search">'+ico('search')+'<span>'+text+'</span></div>'

def row(text, val='', last=False):
    return '<div class="row'+(' last' if last else '')+'"><span>'+text+'</span><span class="rowval">'+val+'</span><em>›</em></div>'

def action(text, secondary=False):
    return '<button class="action'+(' secondary' if secondary else '')+'">'+text+'</button>'

def card(title, content, symbol=None):
    return '<section class="card"><h2>'+('<i class="ico">'+ico(symbol)+'</i>' if symbol else '')+title+'</h2>'+content+'</section>'

def quote(text, source):
    return '<blockquote>'+text+'<small>'+source+' <em>›</em></small></blockquote>'

def page(title, subtitle, content, footer, back='记忆与上下文', plus=False):
    return '<div class="screen"><div class="status"><b>9:41</b><span>▮▮▮ &nbsp; ◒ &nbsp; ▰</span></div><nav><span>‹</span>'+back+'<b class="navtail">'+('＋' if plus else '···')+'</b></nav><header><h1>'+title+'</h1><div class="role"><img src="data:image/png;base64,'+avatar+'"><b>大肥鱼</b><span>'+subtitle+'</span></div></header><main>'+content+'</main><footer>'+footer+'<div class="home"></div></footer></div>'

def diary(day,title,summary,size,meta='已整理'):
    return '<section class="card diary"><div class="date"><b>'+day+'</b><small>10月</small></div><div class="diarybody"><div class="titleline"><h2>'+title+'</h2><em>›</em></div><p>'+summary+'</p><div class="meta"><span>'+meta+' · '+size+' KB</span><span>'+chip('可检索',True)+'</span></div></div></section>'

diary_list = '<div class="summary"><div><b>18<small> 篇日记</small></b><span>每角色每天一个文件</span></div><div class="right"><b>38.6<small> KB</small></b><span>实际文件占用</span></div></div>'+search('搜索日记、日期或关键词')+'<div class="sectiontitle">2026年10月 <span>选择月份 ⌄</span></div>'+diary('31','聊天与记忆的新方案','讨论怎样保存和找回以前的聊天。','1.8')+diary('30','主页布局与安装','确认按钮样式，记录安装待检查项。','2.4')+diary('29','灵动岛舞蹈测试','保留完整时序，等待手机体验。','1.2')+card('每日整理','<div class="row last"><span>下次整理时间</span><b class="rowval">23:30</b></div><p class="hint no-margin">到点待整理，打开时补齐；同一天有新内容时更新原文件。</p>','clock')+'<p class="hint">聊天只检索相关段落，不会把全部日记一起发送。</p>'
diary_detail = '<div class="fileline"><span>2026-10-31.md</span><span>1.8 KB · 19:25 更新</span></div>'+card('今天聊了什么','<p>一起讨论了聊天记忆如何保存、检索，以及如何查看每次请求携带的内容。</p>')+card('确定的事情','<ul class="checklist"><li>主页面采用淡紫简洁布局。</li><li>每角色每天生成独立日记。</li><li>重要约定与日记分开维护。</li></ul>','check')+card('还想聊的事','<p>下次继续聊：哪些内容值得记住，以及怎样让回忆更准确。</p>','clock')+'<section class="card reflection"><h2>角色随笔 <span class="chip quiet">感受</span></h2><p>今天一起把记忆的思路理清了，希望以后能更自然地接上我们聊过的事情。</p><small>这是角色表达，不作为用户事实保存。</small></section>'+card('来源与使用','<p class="hint no-margin">来自当天参与的聊天，可追溯原话。</p>'+row('查看当天原话','16 条')+row('参与日记检索','已开启',True))+'<div class="linkbar"><span>重新整理</span><span class="danger">删除日记</span></div>'

def fact(title,text,mode,source):
    return '<section class="card fact"><div class="titleline"><h2>'+title+'</h2><em>›</em></div><p>'+text+'</p><div class="meta">'+chip(mode,mode!='始终携带')+'<span>'+source+'</span></div></section>'

fact_list = '<div class="summary"><div><b>12<small> 条有效约定</small></b><span>3条固定携带 · 9条按需检索</span></div><div class="right"><b>6.2<small> KB</small></b><span>独立记忆文件</span></div></div>'+search('搜索事实与约定')+'<div class="filters"><b>全部</b><span>始终携带</span><span>按需检索</span><span>停用</span></div>'+fact('沟通偏好','先说结论，再解释必要的细节。','始终携带','手动保存')+fact('主动联系时间','只在10:00–18:00内主动联系。','按需检索','原话确认')+fact('动作素材规则','20秒以内的视频完整取帧，保留原时序。','按需检索','原话确认')+card('有变化时如何处理','<p>新约定确认后更新当前版本，旧版保留为历史，不再继续当作现行要求。</p>','star')
fact_detail = '<div class="inlinechips">'+chip('当前有效')+chip('手动可编辑',True)+'</div><div class="field"><label>记忆标题</label><div class="input">主动联系时间</div></div><div class="field"><label>记忆内容</label><div class="input textarea">只在每天10:00–18:00之间主动联系；其他时间不安排新提醒。</div></div><div class="field"><label>聊天如何使用</label><section class="card choices"><div class="choice"><i class="radio"></i><div><b>始终携带</b><small>每次聊天都包含这条约定。</small></div></div><div class="choice"><i class="radio checked"></i><div><b>按需检索</b><small>问题相关时再加入上下文。</small></div></div><div class="choice"><i class="radio"></i><div><b>停用</b><small>保留文件，聊天暂不读取。</small></div></div></section></div>'+card('原话出处',quote('“18点到第二天早上10点不允许聊天。”','10月31日 · 与大肥鱼私聊'))+'<div class="fileline"><span>文件大小 428 B</span><span>历史版本 ›</span></div><p class="hint">这里只影响聊天记忆；实际联系时段请到主动聊天设置修改。删除记忆不会自动删除旧聊天。</p><div class="linkbar single"><span class="danger">删除这条记忆</span></div>'

def suggestion(title,text,kind,source):
    return '<section class="card suggestion"><div class="titleline"><h2>'+title+'</h2>'+chip(kind,kind=='新记忆')+'</div><p>'+text+'</p><div class="source-inline">'+ico('chat')+'<span>'+source+'</span></div><div class="suggestionactions"><button class="textbutton">暂不保存</button><button class="mini-primary">核对并保存 <em>›</em></button></div></section>'

pending_list = '<div class="notice notice-large"><i class="ico">'+ico('check')+'</i><div><b>3条建议，等待你确认</b><p>确认前不会进入长期记忆或聊天上下文。</p></div></div><div class="tabs"><b>全部 <small>3</small></b><span>新记忆 <small>2</small></span><span>更新约定 <small>1</small></span></div>'+suggestion('主动联系时间','建议将原来的联系时间更新为10:00–18:00。','更新约定','10月31日 · 用户原话可核对')+suggestion('素材处理习惯','完整保留原视频时长和全部帧序。','新记忆','10月31日 · 来自当天聊天')+suggestion('交流习惯','重要的事情先确认，不替用户自行决定。','新记忆','10月31日 · 来自当天聊天')+'<p class="hint">可以修改建议后再保存。不合适的内容可直接丢弃，不会影响原聊天。</p>'
pending_detail = '<div class="inlinechips">'+chip('建议更新已有约定')+'</div>'+card('先核对用户原话',quote('“18点到第二天早上10点不允许聊天。”','10月31日 · 与大肥鱼私聊'),'chat')+'<section class="comparison"><div class="old"><label>原约定</label><p>允许在09:00–18:00主动联系。</p></div><div class="new"><label>建议更新为</label><p>只在10:00–18:00之间主动联系。</p></div></section><div class="field"><label>保存内容 <span>可直接修改</span></label><div class="input textarea">只在每天10:00–18:00之间主动联系；其他时间不安排新提醒。</div></div>'+card('确认后如何处理','<div class="choice"><i class="radio checked"></i><div><b>更新已有约定</b><small>旧版保留为历史，不再参与聊天。</small></div></div>'+row('使用方式','按需检索',True),'check')+'<p class="hint">保存后进入大肥鱼的独立记忆文件夹，其他角色不会自动读取；不会直接修改主动聊天排程。</p><div class="linkbar single"><span class="danger">丢弃这条建议</span></div>'

boards = [
 ('diary','每日日记','按日期查看','日记详情',page('每日日记','每天一篇 · 原话可追溯',diary_list,action('整理今天的聊天'),'记忆与上下文'),page('10月31日的日记','按当天内容整理 · 独立文件',diary_detail,action('编辑这篇日记'),'每日日记')),
 ('facts','事实与约定','已保存的记忆','编辑与携带方式',page('事实与约定','明确事实 · 当前有效',fact_list,action('新建记忆 ＋'),plus=True),page('编辑记忆','仅影响大肥鱼后续聊天',fact_detail,action('保存修改'),'事实与约定')),
 ('pending','待确认记忆','整理建议列表','核对与更新约定',page('待确认记忆','AI整理建议 · 由你决定',pending_list,action('查看自动整理设置',True)),page('核对并保存','确认原话，再写入记忆',pending_detail,action('确认更新约定'),'待确认记忆')),
]

